package dev.wildframe.engine

import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test
import java.io.File
import kotlin.math.abs
import kotlin.math.max

/** Replays golden/ (generated by `python -m golden.generate`) through the Kotlin port. See
 * golden/README.md for the format and comparison rules: exact strings/states/structure, floats
 * to 1e-6 relative / 1e-5 absolute. Every mismatching case is reported, not just the first. */
class GoldenTest {
    private val goldenDir = File(System.getProperty("golden.dir") ?: "../../golden")

    @Suppress("UNCHECKED_CAST")
    private fun load(f: File) = Json.parse(f.readText()) as Map<String, Any?>

    private fun floats(v: Any?): FloatArray = (v as List<*>).map { (it as Number).toFloat() }.toFloatArray()

    private fun detection(d: Map<*, *>) = Detection(
        bbox = floats(d["bbox_xyxy"]),
        keypoints = (d["keypoints"] as List<*>).map { floats(it) }.toTypedArray(),
        detConf = (d["det_conf"] as Number).toDouble(),
        trackId = (d["track_id"] as Number?)?.toInt(),
    )

    private fun ruleJson(o: RuleOutput?): Any? = o?.let {
        mapOf(
            "rule" to it.rule.value, "state" to it.state.value, "reason" to it.reason, "message" to it.message,
            "severity" to it.severity, "correction" to it.correction, "referent" to it.referent, "debug" to it.debug,
        )
    }

    /** Mirror of golden/generate.py decision_json. */
    private fun decisionJson(d: Decision): Map<String, Any?> {
        val s = d.subjectSet
        return mapOf(
            "scene" to mapOf(
                "mode" to s.mode.value, "mode_reason" to s.modeReason, "count" to s.count,
                "count_reliable" to s.countReliable, "primary_track_id" to s.primary?.trackId,
                "union_bbox" to s.unionBbox?.map { it.toDouble() },
                "agreed_yaw" to s.agreedOrientation?.yawState,
                "members" to s.members.map {
                    mapOf(
                        "track_id" to it.trackId, "yaw_state" to it.orientation?.yawState,
                        "facing_vector" to it.orientation?.facingVector?.map { v -> v.toDouble() },
                    )
                },
            ),
            "mode_notice" to d.modeNotice,
            "raw" to d.rawOutputs.entries.associate { it.key.value to ruleJson(it.value) },
            "smoothed" to d.smoothedOutputs.entries.associate { it.key.value to ruleJson(it.value) },
            "ready" to ruleJson(d.ready),
            "chosen" to ruleJson(d.chosen),
        )
    }

    private fun diff(actual: Any?, expected: Any?, path: String): String? {
        if (actual is Number || expected is Number) {
            if (actual !is Number || expected !is Number) return "$path: $actual != $expected"
            val a = actual.toDouble()
            val e = expected.toDouble()
            if (a.isNaN() && e.isNaN()) return null
            return if (abs(a - e) <= max(1e-6 * max(abs(a), abs(e)), 1e-5)) null else "$path: $a != $e"
        }
        if (expected is Map<*, *>) {
            if (actual !is Map<*, *>) return "$path: expected object, got $actual"
            if (actual.keys.map { it.toString() }.toSet() != expected.keys.map { it.toString() }.toSet()) {
                return "$path: keys ${actual.keys.map { it.toString() }.sorted()} != ${expected.keys.map { it.toString() }.sorted()}"
            }
            for (k in expected.keys) diff(actual[k], expected[k], "$path.$k")?.let { return it }
            return null
        }
        if (expected is List<*>) {
            if (actual !is List<*> || actual.size != expected.size) return "$path: $actual != $expected"
            for (i in expected.indices) diff(actual[i], expected[i], "$path[$i]")?.let { return it }
            return null
        }
        return if (actual == expected) null else "$path: '$actual' != '$expected'"
    }

    @Test
    fun decisionCasesMatchPython() {
        val files = File(goldenDir, "cases").listFiles { f -> f.extension == "json" }!!.sortedBy { it.name }
        assertTrue("no golden cases found under ${goldenDir.absolutePath}", files.isNotEmpty())
        val failures = ArrayList<String>()
        for (f in files) {
            val case = load(f)
            @Suppress("UNCHECKED_CAST")
            val engine = Engine(Config(case["rules_config"] as Map<String, Any?>))
            val dims = case["frame_dims"] as List<*>
            val w = (dims[0] as Number).toInt()
            val h = (dims[1] as Number).toInt()
            for ((i, frame) in (case["frames"] as List<*>).withIndex()) {
                frame as Map<*, *>
                val dets = (frame["detections"] as List<*>).map { detection(it as Map<*, *>) }
                val problem = diff(decisionJson(engine.decide(dets, w, h)), frame["expected"], "frame[$i]")
                if (problem != null) {
                    failures.add("${f.nameWithoutExtension}: $problem")
                    break
                }
            }
        }
        assertEquals("golden mismatches:\n" + failures.joinToString("\n"), 0, failures.size)
    }

    @Test
    fun trackerCasesMatchPython() {
        val files = File(goldenDir, "tracker").listFiles { f -> f.extension == "json" }!!.sortedBy { it.name }
        assertTrue(files.isNotEmpty())
        val failures = ArrayList<String>()
        for (f in files) {
            val case = load(f)
            @Suppress("UNCHECKED_CAST")
            val tracker = ByteTracker(Config(case["tracker_config"] as Map<String, Any?>))
            for ((i, frame) in (case["frames"] as List<*>).withIndex()) {
                frame as Map<*, *>
                val boxes = (frame["boxes_xyxy"] as List<*>).map { floats(it) }
                val expected = (frame["expected_track_ids"] as List<*>).map { (it as Number).toInt() }
                val actual = tracker.update(boxes)
                if (actual != expected) {
                    failures.add("${f.nameWithoutExtension}: frame[$i] $actual != $expected")
                    break
                }
            }
        }
        assertEquals("tracker mismatches:\n" + failures.joinToString("\n"), 0, failures.size)
    }
}
